  const recordStudyTimeFromRef = useCallback(() => {
    const subject = selectedSubjectRef.current;
    if (!subject || isBreakTimeRef.current) return;
    const today = new Date().toLocaleDateString('ko-KR');
    if (subject.time < 1) return;
    setStudyStats(prev => {
      const n = { ...prev }; if (!n[today]) n[today] = {}; if (!n[today][subject.name]) n[today][subject.name] = 0;
      n[today][subject.name] += subject.time; return n;
    });
  }, []);
  const recordStudyTime = () => {
    if (!selectedSubject || isBreakTime) return;
    const today = new Date().toLocaleDateString('ko-KR');
    const mins = Math.floor((selectedSubject.time * 60 - timeLeft) / 60);
    if (mins < 1) return;
    setStudyStats(prev => {
      const n = { ...prev }; if (!n[today]) n[today] = {}; if (!n[today][selectedSubject.name]) n[today][selectedSubject.name] = 0;
      n[today][selectedSubject.name] += mins; return n;
    });
  };

