        const o = ctx.createOscillator(), g = ctx.createGain();
        o.connect(g); g.connect(ctx.destination); o.frequency.value = 1047; o.type = 'square';
        g.gain.setValueAtTime(0, t + offset);
        g.gain.linearRampToValueAtTime(0.2, t + offset + 0.01);
        g.gain.setValueAtTime(0.2, t + offset + 0.12);
